-- Registre initial des skills. Tous en « draft » : les process sont des brouillons que Hari valide depuis la vue « Lancer ».
INSERT OR IGNORE INTO skills (id, name, scope, location, when_to_use, keywords, process, status, position) VALUES
('cockpit','cockpit','projet','dépôt appmee : .claude/skills/cockpit','Enregistrer un livrable (artefact, document, page, code livré) dans le cockpit, avec explication, lien et plan d''action.','cockpit,livrable,logue,enregistre,mets à jour le cockpit','1. Identifier le projet. 2. Ajouter le livrable (table deliverables). 3. Si pertinent, ajouter le plan d''action en étapes. 4. Confirmer en une phrase.','draft',1),
('studio-lancement-app','studio-lancement-app','projet','dépôt appmee : .claude/skills/studio-lancement-app','Créer vidéos, carrousels, visuels et posts de lancement d''une app à partir de ses vraies captures et des mots de sa landing.','vidéo,video,lancement,carrousel,reel,linkedin,product hunt,miniature,visuel,post,captures,diaporama,storyboard,voix off','1. Brief : captures + mots de la landing. 2. Scénario et storyboard. 3. Production aux formats de chaque réseau. 4. Contrôle qualité. 5. Enregistrer les livrables dans le cockpit.','draft',2),
('veille-youtube','veille-youtube','compte','compte claude.ai','Nouvelle recherche de veille YouTube : top vidéos longues par ratio vues/abonnés, angle, 3 titres, miniature signature.','veille,youtube,ratio,titres,miniature,vidéos longues','1. Cibler le sujet. 2. Lancer la recherche. 3. Livrer top vidéos, angle, 3 titres, miniature, pattern. 4. Ajouter à l''artefact Veille YouTube.','draft',3),
('demo-veille-slideshow','demo-veille-slideshow','compte','compte claude.ai','Refaire ou mettre à jour le diaporama animé 16:9 expliquant le dashboard Veille YouTube.','diaporama veille,slideshow,dashboard veille','1. Relire l''état du dashboard Veille. 2. Mettre à jour le diaporama. 3. Enregistrer le livrable dans le cockpit.','draft',4),
('maestro','maestro','projet','dépôt appmee : .claude/skills/maestro (version Claude cloud ; skill compagnon : cadrage-projet)','Mission large et autonome, tout type de livrable, de sujet ou de format (stratégie, système, dossier, kit, contenus, pages, code, données, vidéos, emails) : l''utilisateur cadre une fois, valide une fois ; MAESTRO fait benchmark, débat d''experts, production, auto-audit chiffré et livraison.','maestro,mission,lance une mission,reprends la mission,stratégie,strategie,système,dossier complet,kit,go-to-market,benchmark,experts,cadrage,livre tout seul,distribution,plan complet','0. Triage et mode (éclair, standard, complète), puis cadrage via le skill cadrage-projet : brief.md, equipe.md, TOOLING.md. GATE UNIQUE : un seul GO de Hari, puis lock-brief.sh fige le brief (changement = avenant). 1. Benchmark de cas éprouvés (ou dispense motivée). 2. Débat des rôles sur les décisions structurantes. 3. Production de chaque livrable selon son format, état commité et poussé sur la branche après chacun. 4. Auto-audit chiffré : 80/100, aucun critère à 0-1, 2 passes max. 5. Livraison. check-mission.sh bloque chaque phase tant que les verrous ne sont pas verts. Arrêt obligatoire avant toute dépense, publication, envoi, action irréversible ou production. Aucune écriture au cockpit sans demande.','draft',5),
('deep-research','deep-research','compte','compte claude.ai','Recherche multi-sources, comparaison d''options, analyse de marché, rapport de synthèse.','recherche,comparer,marché,marche,analyse,étude,etude,concurrents,veille marché','1. Cadrer la question. 2. Chercher plusieurs sources. 3. Synthétiser en rapport sourcé. 4. Enregistrer le livrable dans le cockpit.','draft',6),
('docx','docx','compte','compte claude.ai','Créer ou modifier un document Word (.docx).','word,docx,document,lettre,courrier,contrat','1. Cadrer le document. 2. Produire le .docx. 3. Relire. 4. Enregistrer le livrable.','draft',7),
('pptx','pptx','compte','compte claude.ai','Créer ou modifier une présentation PowerPoint (.pptx).','powerpoint,pptx,slides,présentation,presentation,deck,pitch','1. Cadrer le message et le public. 2. Produire le .pptx. 3. Relire. 4. Enregistrer le livrable.','draft',8),
('xlsx','xlsx','compte','compte claude.ai','Créer, corriger ou analyser un tableur (.xlsx, .csv).','tableur,excel,xlsx,csv,feuille,budget','1. Cadrer les données. 2. Produire ou corriger le tableur. 3. Vérifier les formules. 4. Enregistrer le livrable.','draft',9),
